#!/usr/bin/env python3
"""
企业普法培训方案

**普法培训最常见的失败是「讲得很专业，听完没人改行为」。**

法律人讲课容易滑向法条串讲，但企业员工要的不是知识，是**「我该怎么做、
不该怎么做、出事了找谁」**。判断标准很简单：听完之后，
他在具体场景里的动作会不会变。

三个决定成败的变量：
  受众 —— 高管 / 中层 / 一线员工，关心的完全不同
  场景 —— 培训要围绕他们真实会遇到的情形，不是法律体系
  行为 —— 每个知识点必须落到一个可执行的动作

用法：
    training.py --audience 一线员工 --topic 数据合规 --duration 60
    training.py --list
"""
import argparse, json, sys

AUDIENCE = {
    "高管": {
        "关心": "决策风险、个人责任、公司暴露面",
        "深度": "结论与风险敞口为主，法律细节点到为止",
        "时长": "30–45 分钟，**再长注意力就散了**",
        "形式": "案例 + 数据 + 一页纸风险图",
        "忌": "**不要讲法条。** 高管要的是「这事我签不签」「我个人会不会担责」",
        "落点": ["哪些决定必须过法务", "个人责任的边界（董监高责任、法定代表人风险）",
                 "出事时的第一动作与汇报路径"],
    },
    "中层管理者": {
        "关心": "本部门的合规红线、管理动作、如何向下传导",
        "深度": "红线清单 + 典型情形判断 + 流程节点",
        "时长": "60–90 分钟",
        "形式": "情景判断 + 小组讨论 + 流程图",
        "忌": "不要只讲「不能做什么」，**要讲「该怎么做」**——否则业务会绕开",
        "落点": ["本部门的三条红线", "哪些动作必须留痕", "什么情况必须上报或找法务"],
    },
    "一线员工": {
        "关心": "我具体怎么做、做错了会怎样",
        "深度": "**只讲和他岗位相关的**，不做体系介绍",
        "时长": "30–45 分钟",
        "形式": "**真实场景 + 对错对照 + 一张卡片**",
        "忌": "**绝对不要讲法律体系。** 讲「合同法的基本原则」对一线员工毫无用处",
        "落点": ["这三种情况必须停下来问", "这些话不能对客户说", "这些材料必须留存"],
    },
    "法务/合规岗": {
        "关心": "规则细节、判断标准、疑难情形",
        "深度": "可以深，但要有判断框架而非罗列",
        "时长": "90–120 分钟",
        "形式": "规则 + 案例分析 + 疑难研讨",
        "忌": "不要停在规则复述，**要给判断方法**",
        "落点": ["判断框架", "边界情形怎么处理", "什么时候找外部律师"],
    },
    "销售/市场": {
        "关心": "话术边界、承诺风险、合同签署",
        "深度": "场景化，**围绕他们每天真实说的话**",
        "时长": "45 分钟",
        "形式": "话术对错对照 + 真实处罚案例",
        "忌": "不要泛泛讲广告法，**要给具体的话术清单**",
        "落点": ["这些词不能说（绝对化用语）", "什么承诺算合同", "折扣与赠品的边界"],
    },
}

TOPICS = {
    "数据合规": {
        "场景": ["收集用户手机号做营销", "把客户名单给合作方", "员工离职带走客户资料",
                 "用第三方 SDK", "跨境同步数据"],
        "红线": ["未经单独同意对外提供个人信息", "超出告知目的使用", "未成年人信息未经监护人同意"],
    },
    "合同管理": {
        "场景": ["微信里谈定的条件算不算数", "对方发来的模板直接签", "盖章前没让法务看",
                 "口头承诺交期", "邮件确认变更"],
        "红线": ["超授权签约", "先履行后签合同", "重要变更不走书面"],
    },
    "劳动用工": {
        "场景": ["试用期不合格辞退", "员工严重违纪", "调岗降薪", "加班审批", "竞业限制"],
        "红线": ["规章制度未经民主程序就据以处罚", "口头辞退", "未签书面合同超一个月"],
    },
    "反商业贿赂": {
        "场景": ["给客户送礼", "接受供应商招待", "赞助与捐赠", "介绍费与佣金"],
        "红线": ["以回扣促成交易", "账外暗中给予财物", "利用职务便利索取好处"],
    },
    "知识产权": {
        "场景": ["用网图做宣传", "员工职务发明", "开源软件使用", "竞品对比宣传"],
        "红线": ["未授权使用他人作品", "侵犯商业秘密", "虚假或引人误解的对比"],
    },
    "广告与宣传": {
        "场景": ["写文案用「最」「第一」", "引用用户评价", "医疗健康类表述", "直播带货话术"],
        "红线": ["绝对化用语", "虚假宣传", "未标明广告"],
    },
}


def main():
    p = argparse.ArgumentParser(description="企业普法培训方案",
                                formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument("--audience", choices=list(AUDIENCE), help="受众")
    p.add_argument("--topic", help=f"主题：{list(TOPICS)}")
    p.add_argument("--duration", type=int, help="时长（分钟）")
    p.add_argument("--list", action="store_true")
    args = p.parse_args()

    if args.list:
        print(json.dumps({"受众": {k: v["关心"] for k, v in AUDIENCE.items()},
                          "主题": {k: v["场景"][:3] for k, v in TOPICS.items()}},
                         ensure_ascii=False, indent=2))
        return
    if not args.audience:
        p.error("需指定 --audience，可选值见 --list")

    a = AUDIENCE[args.audience]
    t = TOPICS.get(args.topic or "", None)

    warn = []
    if args.duration:
        rec = a["时长"]
        if args.audience in ("高管", "一线员工") and args.duration > 60:
            warn.append(f"计划 {args.duration} 分钟，但{args.audience}的建议时长是 {rec}。"
                        f"**超时的部分基本没人在听**，不如砍内容")

    out = {
        "受众": args.audience,
        "受众画像": {"关心什么": a["关心"], "内容深度": a["深度"],
                     "建议时长": a["时长"], "适合形式": a["形式"]},
        "⚠️ 这类受众最忌": a["忌"],
        "必须落到的行为": a["落点"],
    }
    if t:
        out["主题"] = args.topic
        out["真实场景（围绕这些讲）"] = t["场景"]
        out["红线（必须记住的）"] = t["红线"]
    else:
        out["主题"] = args.topic or "未指定"
        out["提示_主题"] = ("未匹配到内置主题。**内容仍应围绕受众的真实场景组织**，"
                            "而不是按法律体系展开")

    out["设计原则"] = [
        "**判断标准只有一个：听完之后，他在具体场景里的动作会不会变。** "
        "讲得再专业，行为不变就是白讲",
        "**每个知识点必须落到一个可执行的动作。** "
        "「要注意个人信息保护」不是动作；「收集手机号做营销前，先问法务要不要单独同意」是",
        "**用他们真实会遇到的场景，不用法律体系。** "
        "一线员工不需要知道什么是格式条款，需要知道「客户要改合同条款时找谁」",
        "**案例必须脱敏。** 用本公司真实案例效果最好，但**必须转「文件脱敏」处理**；"
        "用公开案例的，核实来源",
        "**留一页纸带走。** 培训结束后能贴在工位上的卡片，比两小时的课件有用",
        "**留痕。** 签到表、课件、考核记录——**培训过没培训过，在合规检查与劳动争议中是两回事**",
    ]
    if warn:
        out["⚠️ 时长提示"] = warn
    print(json.dumps(out, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()
